Status validate_political_governance_agency_sources(const PoliticalGovernanceAgencyContext& x){
 using namespace governance_agency_detail;auto through=historical_through(x);if(!through.ok)return {false,{},through.error};auto valid=validate_political_governance_agency_catalog(x.common,x.politics_catalog,x.governance_catalog,x.organization_catalog,x.catalog);if(!valid.ok)return valid;
 const auto total=x.state.offers.size()+x.state.answers.size()+x.state.revocations.size()+x.state.issues.size();if(x.state.version!=x.catalog.version||(x.state.version!=1&&x.state.version!=2)||total>4096||!x.seat||!x.player_before)return common_failure("PoliticalGovernanceAgencyHistoricalReadersRequired");
 if((x.state.version==1&&(x.intents||!x.state.authored_origins.empty()))||(x.state.version==2&&!x.intents))return common_failure("GovernanceAgencyIntentVersionPairRequired");
 if(x.intents){valid=validate_political_governance_agency_intents(*x.intents,x.common_catalog,x.politics_catalog,x.organization_catalog,x.catalog);if(!valid.ok)return valid;}
 struct Live {const PoliticalGovernanceAgencyOffer* offer=nullptr;const PoliticalGovernanceAgencyAnswer* answer=nullptr;bool closed=false;Integer issued=0;};std::map<StableId,Live> live;std::set<StableId> seen,authorities;Integer previous=0,last_tick=0;
 for(const auto& row:x.common.state().facts.rows()){
  const auto& h=row.second;if(h.domain!=political_governance_agency_domain){if(h.kind.rfind("political_governance_agency_",0)==0)return common_failure("PoliticalGovernanceAgencyFactDomainMismatch",row.first);continue;}
  auto n=political_governance_agency_fact_sequence(x.common,row.first,h.kind);if(!n||*n<=previous||!seen.insert(row.first).second)return common_failure("PoliticalGovernanceAgencyHistoryOrderMismatch",row.first);Integer tick=0;StableId actor;const PoliticalGovernanceAgencyOffer* offer=nullptr;
  if(h.kind=="political_governance_agency_offered"){
   const auto* o=x.state.offers.find(row.first);const auto* p=o?x.catalog.policies.find(o->policy_id):nullptr;const auto* j=p?x.politics_catalog.jurisdictions.find(p->jurisdiction_id):nullptr;if(!o||o->id!=row.first||!p||!j||o->tick<0||o->tick>std::numeric_limits<Integer>::max()-p->mandate_ticks||o->organization_id!=j->political_organization_id||o->office_id!=p->office_id||o->issuer_actor_id==o->delegate_actor_id||o->appointment_grant_id!=p->appointment_grant_id||o->commission_grant_id!=p->commission_grant_id||o->jurisdiction_revision!=j->revision)return common_failure("PoliticalGovernanceAgencyOfferMismatch",row.first);
   auto until=o->tick+p->mandate_ticks;for(const auto& id:{p->appointment_grant_id,p->commission_grant_id}){const auto* g=x.organization_catalog.grants.find(id);if(g->valid_until)until=std::min(until,*g->valid_until);}if(o->response_before_tick!=o->tick+p->response_ticks||o->valid_through_tick!=until||o->valid_through_tick<o->response_before_tick)return common_failure("PoliticalGovernanceAgencyWindowMismatch",row.first);
   for(const auto& old:live)if(old.second.offer->policy_id==o->policy_id&&old.second.offer->office_epoch==o->office_epoch&&!old.second.closed&&o->tick<=old.second.offer->valid_through_tick&&(old.second.answer?old.second.answer->accept:o->tick<old.second.offer->response_before_tick))return common_failure("PoliticalGovernanceAgencyAlreadyPending",row.first);
   valid=office_before(x,*o,o->tick,o->id);if(!valid.ok)return valid;valid=grant_at(x,*p,o->tick);if(!valid.ok)return valid;for(const auto& person:{o->issuer_actor_id,o->delegate_actor_id}){valid=person_before(x,person,o->tick,o->id,o->organization_id);if(!valid.ok)return valid;}valid=x.seat(*p,o->tick,o->id);if(!valid.ok)return valid;live.emplace(o->id,Live{o});offer=o;tick=o->tick;actor=o->issuer_actor_id;
  }else if(h.kind=="political_governance_agency_accepted"||h.kind=="political_governance_agency_declined"){
   const auto* a=x.state.answers.find(row.first);auto found=a?live.find(a->offer_fact_id):live.end();if(!a||a->id!=row.first||found==live.end()||found->second.answer||found->second.closed)return common_failure("PoliticalGovernanceAgencyAnswerMismatch",row.first);auto& active=found->second;offer=active.offer;const auto& p=*x.catalog.policies.find(offer->policy_id);if(a->actor_id!=offer->delegate_actor_id||a->tick<offer->tick||a->tick>=offer->response_before_tick||a->accept!=(h.kind=="political_governance_agency_accepted"))return common_failure("PoliticalGovernanceAgencyAnswerMismatch",row.first);valid=person_before(x,a->actor_id,a->tick,a->id,offer->organization_id);if(!valid.ok)return valid;
   if(a->accept){valid=office_before(x,*offer,a->tick,a->id);if(!valid.ok)return valid;valid=grant_at(x,p,a->tick);if(!valid.ok)return valid;valid=person_before(x,offer->issuer_actor_id,a->tick,a->id,offer->organization_id);if(!valid.ok)return valid;valid=x.seat(p,a->tick,a->id);if(!valid.ok)return valid;}active.answer=a;active.closed=!a->accept;actor=a->actor_id;tick=a->tick;
  }else if(h.kind=="political_governance_agency_revoked"){
   const auto* r=x.state.revocations.find(row.first);auto found=r?live.find(r->offer_fact_id):live.end();if(!r||r->id!=row.first||found==live.end()||found->second.closed)return common_failure("PoliticalGovernanceAgencyRevocationMismatch",row.first);auto& active=found->second;offer=active.offer;const auto& p=*x.catalog.policies.find(offer->policy_id);if(r->issuer_actor_id!=offer->issuer_actor_id||r->office_epoch!=offer->office_epoch||r->tick<offer->tick||r->tick>offer->valid_through_tick)return common_failure("PoliticalGovernanceAgencyRevocationMismatch",row.first);valid=office_before(x,*offer,r->tick,r->id);if(!valid.ok)return valid;valid=grant_at(x,p,r->tick);if(!valid.ok)return valid;valid=person_before(x,r->issuer_actor_id,r->tick,r->id,offer->organization_id);if(!valid.ok)return valid;valid=x.seat(p,r->tick,r->id);if(!valid.ok)return valid;active.closed=true;actor=r->issuer_actor_id;tick=r->tick;
  }else if(h.kind=="political_governance_agency_issued"){
   const auto* issue=x.state.issues.find(row.first);auto found=issue?live.find(issue->offer_fact_id):live.end();if(!issue||issue->id!=row.first||found==live.end()||!found->second.answer||!found->second.answer->accept||found->second.closed)return common_failure("PoliticalGovernanceAgencyIssueMismatch",row.first);auto& active=found->second;offer=active.offer;const auto& p=*x.catalog.policies.find(offer->policy_id);const auto& j=*x.politics_catalog.jurisdictions.find(p.jurisdiction_id);const auto* a=x.governance.authorities.find(issue->authority_fact_id);const auto* ah=x.common.state().facts.find(issue->authority_fact_id);auto an=organization_instance_sequence(issue->authority_fact_id,"politics_governance_agency_authority");auto pos=std::find(x.common.state().facts.order().begin(),x.common.state().facts.order().end(),issue->id);
   if(!a||!ah||ah->kind!=governance_authority_fact_kind||ah->domain!="politics"||!an||*n==std::numeric_limits<Integer>::max()||*an!=*n+1||pos==x.common.state().facts.order().end()||++pos==x.common.state().facts.order().end()||*pos!=issue->authority_fact_id||!authorities.insert(a->id).second||issue->acceptance_fact_id!=active.answer->id||issue->delegate_actor_id!=offer->delegate_actor_id||issue->tick<active.answer->tick||issue->tick>offer->valid_through_tick||++active.issued>p.maximum_issues||a->issuer_actor_id!=offer->issuer_actor_id||a->executor_actor_id!=issue->executor_actor_id||a->office_id!=offer->office_id||a->organization_id!=offer->organization_id||a->authority_epoch!=offer->office_epoch||a->jurisdiction_revision!=offer->jurisdiction_revision||a->grant_id!=p.commission_grant_id||a->policy_id!=p.commission_policy_id||a->jurisdiction_id!=p.jurisdiction_id||a->site_id!=j.seat_place_id||a->public_wallet_id!=j.public_wallet_id||a->public_inventory_id!=p.public_inventory_id||a->issued_tick!=issue->tick)return common_failure("PoliticalGovernanceAgencyOriginalApprovalMismatch",row.first);
   valid=office_before(x,*offer,issue->tick,issue->id);if(!valid.ok)return valid;valid=grant_at(x,p,issue->tick);if(!valid.ok)return valid;for(const auto& person:{offer->issuer_actor_id,issue->delegate_actor_id}){valid=person_before(x,person,issue->tick,issue->id,offer->organization_id);if(!valid.ok)return valid;}valid=x.seat(p,issue->tick,issue->id);if(!valid.ok)return valid;actor=issue->delegate_actor_id;tick=issue->tick;
  }else return common_failure("PoliticalGovernanceAgencyUnknownFact",row.first);
  if(tick<last_tick||tick>x.common.tick())return common_failure("PoliticalGovernanceAgencyHistoryClockMismatch",row.first);valid=player_before(x,actor,tick,row.first);if(!valid.ok)return valid;last_tick=tick;previous=*n;
 }
 for(const auto& origin:x.state.authored_origins.rows())if(!seen.count(origin.first)||x.state.revocations.find(origin.first))return common_failure("GovernanceAgencyIntentOriginCoverageMismatch",origin.first);
 if(seen.size()!=total)return common_failure("PoliticalGovernanceAgencyPayloadCoverageMismatch");return common_success();
}
